        polishBoxes.autoZoom.isEnabled = screen
        let keys = screen && recordShortcutsCheckbox.state == .on
        polishBoxes.shortcutOverlays.isEnabled = keys
        polishBoxes.speedUpTyping.isEnabled = keys
    }
